/* Ícones e microinterações uniformes para todas as telas do RH. */
(function(root){'use strict';
const paths={add:'M12 5v14 M5 12h14',edit:'M12 20h9 M16 4l4 4-12 12H4v-4z',download:'M12 3v12 M7 10l5 5 5-5 M4 18v3h16v-3',upload:'M12 16V4 M7 9l5-5 5 5 M4 17v4h16v-4',search:'M11 19a8 8 0 1 0 0-16 8 8 0 0 0 0 16 M21 21l-4.35-4.35',reset:'M3 12a9 9 0 1 0 3-6.7 M3 3v6h6',user:'M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2 M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8',check:'M20 6L9 17l-5-5',close:'M18 6L6 18 M6 6l12 12',copy:'M8 8h13v13H8z M16 8V3H3v13h5',calendar:'M3 5h18v16H3z M3 10h18 M7 2v6 M17 2v6'};
const icon=k=>'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="'+paths[k]+'"/></svg>';
function decorateButtons(){if(!document.querySelector('.hr-hero'))return;document.querySelectorAll('#main .button, .hr-editor .button').forEach(btn=>{if(btn.querySelector('svg'))return;let label=(btn.textContent||'').toLowerCase(),k=btn.matches('[data-hr-toggle]')?'check':btn.matches('[data-hr-person],[data-hr-edit],[data-hr-extra-edit]')?'edit':btn.matches('[data-hr-extra-new],#hrNew,#hrNewDocument')?'add':btn.matches('#hrExport')?'download':btn.matches('#hrImport')?'upload':btn.matches('#hrClearFilters')?'reset':label.includes('importar')||label.includes('planilha')?'upload':label.includes('exportar')||label.includes('pdf')?'download':label.includes('salvar')?'check':label.includes('ficha')?'user':label.includes('copiar')?'copy':label.includes('editar')?'edit':label.includes('novo')?'add':label.includes('fechar')||label.includes('cancelar')?'close':null;if(k)btn.insertAdjacentHTML('afterbegin',icon(k))});}
function enhance(scope){const orig=scope?.attach;if(!orig)return;scope.attach=function(...args){const result=orig.apply(this,args);decorateButtons();return result;};}
enhance(root.EngefexRH);enhance(root.EngefexHRExtra);
})(window);
